import{_ as s,o as e,c as o,ag as t}from"./chunks/framework.VvOSaRrC.js";const i="/kroot-docs/assets/img-01.DclEOGGA.png",r="/kroot-docs/assets/img-02.CKYUxCgm.png",n="/kroot-docs/assets/img-03.Bz_ZwuB-.png",d="/kroot-docs/assets/img-04.CE7-WOIx.png",p="/kroot-docs/assets/img-05.B8v2S5Xw.png",c="/kroot-docs/assets/img-06.KW51MkMB.png",l="/kroot-docs/assets/img-07.wdAJw5xn.png",h="/kroot-docs/assets/img-08.pm9kmhJX.png",m="/kroot-docs/assets/img-09.DO0naMOv.png",g="/kroot-docs/assets/img-10.g9Ei7rTr.png",k="/kroot-docs/assets/img-11.DmHPjOl9.png",b="/kroot-docs/assets/img-12.DPk0s-5y.png",u="/kroot-docs/assets/img-13.DNLneiIq.png",_="/kroot-docs/assets/img-14.DY0xJWzX.png",q="/kroot-docs/assets/img-15.CCT9mhPv.png",C="/kroot-docs/assets/img-16.CU0gTXm2.png",f="/kroot-docs/assets/img-17.pggU1tUd.png",B="/kroot-docs/assets/img-18.-wmBqEU3.png",x="/kroot-docs/assets/img-19.Du9zuh1p.png",v="/kroot-docs/assets/img-20.lWonEIsS.png",A="/kroot-docs/assets/img-21.BFt05KBL.png",P="/kroot-docs/assets/img-22.CSVDAd0t.png",W=JSON.parse('{"title":"Node.js 설치 가이드 (Windows / Mac)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/nodejs-install.md","filePath":"guides/nodejs-install.md"}'),F={name:"guides/nodejs-install.md"};function w(y,a,N,j,S,T){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="node-js-설치-가이드-windows-mac" tabindex="-1">Node.js 설치 가이드 (Windows / Mac) <a class="header-anchor" href="#node-js-설치-가이드-windows-mac" aria-label="Permalink to &quot;Node.js 설치 가이드 (Windows / Mac)&quot;">​</a></h1><p>Node.js를 설치하면 함께 제공되는 <code>npm</code>을 사용할 수 있다. 이 책에서는 Claude Code를 <code>npm</code>으로 설치하므로 Node.js가 반드시 필요하다.</p><p>처음 설치하는 사람은 <strong>LTS(장기 지원) 버전</strong>을 선택하면 된다.</p><ul><li>공식 다운로드: <a href="https://nodejs.org/ko" target="_blank" rel="noreferrer">https://nodejs.org/ko</a></li><li>본 가이드 출처(설치 화면): <a href="https://happy-metamong.tistory.com/26" target="_blank" rel="noreferrer">https://happy-metamong.tistory.com/26</a></li></ul><hr><h2 id="a-windows에-설치하기" tabindex="-1">A. Windows에 설치하기 <a class="header-anchor" href="#a-windows에-설치하기" aria-label="Permalink to &quot;A. Windows에 설치하기&quot;">​</a></h2><h3 id="a-1-설치-파일-다운로드" tabindex="-1">A-1. 설치 파일 다운로드 <a class="header-anchor" href="#a-1-설치-파일-다운로드" aria-label="Permalink to &quot;A-1. 설치 파일 다운로드&quot;">​</a></h3><p>Node.js 공식 다운로드 페이지에 접속해 LTS 버전을 선택한다.</p><p><img src="'+i+'" alt="Node.js 다운로드 페이지 (Windows)"></p><h3 id="a-2-시스템-종류-확인-선택" tabindex="-1">A-2. 시스템 종류 확인 (선택) <a class="header-anchor" href="#a-2-시스템-종류-확인-선택" aria-label="Permalink to &quot;A-2. 시스템 종류 확인 (선택)&quot;">​</a></h3><p>내 컴퓨터가 64비트인지 확인하려면 <code>시스템 &gt; 정보</code>에서 시스템 종류를 확인한다. 대부분의 최신 PC는 64비트(x64)다.</p><p><img src="'+r+'" alt="Windows 시스템 정보 화면"></p><h3 id="a-3-내려받은-설치-파일-실행" tabindex="-1">A-3. 내려받은 설치 파일 실행 <a class="header-anchor" href="#a-3-내려받은-설치-파일-실행" aria-label="Permalink to &quot;A-3. 내려받은 설치 파일 실행&quot;">​</a></h3><p>다운로드 폴더에서 <code>node-vXX.X.X-x64.msi</code> 설치 파일을 실행한다.</p><p><img src="'+n+'" alt="다운로드한 설치 파일"></p><h3 id="a-4-설치-마법사-시작" tabindex="-1">A-4. 설치 마법사 시작 <a class="header-anchor" href="#a-4-설치-마법사-시작" aria-label="Permalink to &quot;A-4. 설치 마법사 시작&quot;">​</a></h3><p><code>Welcome to the Node.js Setup Wizard</code> 화면에서 <code>Next</code>를 누른다.</p><p><img src="'+d+'" alt="Node.js Setup 초기 화면"></p><h3 id="a-5-라이선스-동의" tabindex="-1">A-5. 라이선스 동의 <a class="header-anchor" href="#a-5-라이선스-동의" aria-label="Permalink to &quot;A-5. 라이선스 동의&quot;">​</a></h3><p><code>I accept the terms in the License Agreement</code> 체크박스를 선택하고 <code>Next</code>를 누른다.</p><p><img src="'+p+'" alt="라이선스 동의 화면"></p><h3 id="a-6-설치-경로-설정" tabindex="-1">A-6. 설치 경로 설정 <a class="header-anchor" href="#a-6-설치-경로-설정" aria-label="Permalink to &quot;A-6. 설치 경로 설정&quot;">​</a></h3><p>기본 경로(<code>C:\\Program Files\\nodejs\\</code>)를 유지하고 <code>Next</code>를 누른다.</p><p><img src="'+c+'" alt="설치 폴더 경로 설정 화면"></p><h3 id="a-7-custom-setup" tabindex="-1">A-7. Custom Setup <a class="header-anchor" href="#a-7-custom-setup" aria-label="Permalink to &quot;A-7. Custom Setup&quot;">​</a></h3><p><code>Node.js runtime</code>, <code>npm package manager</code>, <code>Add to PATH</code>가 선택되어 있는지 확인하고 <code>Next</code>를 누른다.</p><p><img src="'+l+'" alt="설치 구성 요소 선택 화면"></p><h3 id="a-8-tools-for-native-modules-선택" tabindex="-1">A-8. Tools for Native Modules (선택) <a class="header-anchor" href="#a-8-tools-for-native-modules-선택" aria-label="Permalink to &quot;A-8. Tools for Native Modules (선택)&quot;">​</a></h3><p>추가 개발 도구(Python, Visual Studio Build Tools) 설치 옵션이다. 단순히 Claude Code만 사용할 목적이라면 체크하지 않아도 된다. 그대로 <code>Next</code>를 누른다.</p><p><img src="'+h+'" alt="추가 개발 도구 설치 옵션"></p><h3 id="a-9-설치-시작" tabindex="-1">A-9. 설치 시작 <a class="header-anchor" href="#a-9-설치-시작" aria-label="Permalink to &quot;A-9. 설치 시작&quot;">​</a></h3><p><code>Install</code> 버튼을 눌러 설치를 시작한다.</p><p><img src="'+m+'" alt="설치 준비 완료 화면"></p><h3 id="a-10-설치-진행" tabindex="-1">A-10. 설치 진행 <a class="header-anchor" href="#a-10-설치-진행" aria-label="Permalink to &quot;A-10. 설치 진행&quot;">​</a></h3><p>설치가 진행된다. 잠시 기다린다.</p><p><img src="'+g+'" alt="설치 진행 화면"></p><h3 id="a-11-설치-완료" tabindex="-1">A-11. 설치 완료 <a class="header-anchor" href="#a-11-설치-완료" aria-label="Permalink to &quot;A-11. 설치 완료&quot;">​</a></h3><p><code>Finish</code>를 눌러 설치를 종료한다.</p><p><img src="'+k+'" alt="설치 완료 화면"></p><blockquote><p>A-8에서 추가 개발 도구를 체크했다면, 설치 종료 후 검은색 명령창이 자동으로 열려 Python과 Visual Studio Build Tools를 추가로 설치한다. 안내에 따라 진행하면 된다.</p><p><img src="'+b+`" alt="추가 도구 설치 스크립트 창"></p></blockquote><h3 id="a-12-설치-확인" tabindex="-1">A-12. 설치 확인 <a class="header-anchor" href="#a-12-설치-확인" aria-label="Permalink to &quot;A-12. 설치 확인&quot;">​</a></h3><p>명령 프롬프트(또는 Git Bash)를 열고 아래 명령으로 버전을 확인한다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p><img src="`+u+'" alt="버전 확인 명령어 실행 결과"></p><p>버전 번호가 보이면 Windows 설치가 완료된 것이다.</p><hr><h2 id="b-mac에-설치하기-pkg-설치-프로그램" tabindex="-1">B. Mac에 설치하기 (pkg 설치 프로그램) <a class="header-anchor" href="#b-mac에-설치하기-pkg-설치-프로그램" aria-label="Permalink to &quot;B. Mac에 설치하기 (pkg 설치 프로그램)&quot;">​</a></h2><h3 id="b-1-설치-파일-다운로드" tabindex="-1">B-1. 설치 파일 다운로드 <a class="header-anchor" href="#b-1-설치-파일-다운로드" aria-label="Permalink to &quot;B-1. 설치 파일 다운로드&quot;">​</a></h3><p>Node.js 공식 페이지에서 macOS용 설치 프로그램(<code>.pkg</code>)을 내려받는다.</p><p><img src="'+_+'" alt="Node.js 다운로드 페이지 (macOS)"></p><h3 id="b-2-내려받은-pkg-파일-실행" tabindex="-1">B-2. 내려받은 pkg 파일 실행 <a class="header-anchor" href="#b-2-내려받은-pkg-파일-실행" aria-label="Permalink to &quot;B-2. 내려받은 pkg 파일 실행&quot;">​</a></h3><p>다운로드 폴더에서 <code>node-vXX.X.X.pkg</code> 파일을 실행한다.</p><p><img src="'+q+'" alt="다운로드한 pkg 파일"></p><h3 id="b-3-소개-화면" tabindex="-1">B-3. 소개 화면 <a class="header-anchor" href="#b-3-소개-화면" aria-label="Permalink to &quot;B-3. 소개 화면&quot;">​</a></h3><p>설치 프로그램이 <code>node</code>와 <code>npm</code>을 <code>/usr/local/bin</code>에 설치한다고 안내한다. <code>계속</code>을 누른다.</p><p><img src="'+C+'" alt="Node.js 설치 소개 화면"></p><h3 id="b-4-사용권-계약-동의" tabindex="-1">B-4. 사용권 계약 동의 <a class="header-anchor" href="#b-4-사용권-계약-동의" aria-label="Permalink to &quot;B-4. 사용권 계약 동의&quot;">​</a></h3><p>라이선스 동의 화면에서 <code>계속</code> → <code>동의</code>를 누른다.</p><p><img src="'+f+'" alt="사용권 계약 화면"></p><h3 id="b-5-설치-유형-선택" tabindex="-1">B-5. 설치 유형 선택 <a class="header-anchor" href="#b-5-설치-유형-선택" aria-label="Permalink to &quot;B-5. 설치 유형 선택&quot;">​</a></h3><p><code>Macintosh HD</code>에 표준 설치를 선택하고 <code>설치</code>를 누른다. Mac 비밀번호를 입력하라는 화면이 나오면 입력한다. (입력 시 화면에 글자가 보이지 않아도 정상이다.)</p><p><img src="'+B+'" alt="설치 유형 선택 화면"></p><h3 id="b-6-설치-완료" tabindex="-1">B-6. 설치 완료 <a class="header-anchor" href="#b-6-설치-완료" aria-label="Permalink to &quot;B-6. 설치 완료&quot;">​</a></h3><p><code>설치가 성공적으로 완료되었습니다</code> 메시지가 나오면 <code>닫기</code>를 누른다.</p><p><img src="'+x+`" alt="설치 완료 화면"></p><h3 id="b-7-설치-확인" tabindex="-1">B-7. 설치 확인 <a class="header-anchor" href="#b-7-설치-확인" aria-label="Permalink to &quot;B-7. 설치 확인&quot;">​</a></h3><p>터미널을 열고 아래 명령으로 버전을 확인한다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p><img src="`+v+'" alt="버전 확인 명령어 실행 (macOS)"></p><p>버전 번호가 보이면 정상이다.</p><hr><h2 id="c-mac에-설치하기-homebrew" tabindex="-1">C. Mac에 설치하기 (Homebrew) <a class="header-anchor" href="#c-mac에-설치하기-homebrew" aria-label="Permalink to &quot;C. Mac에 설치하기 (Homebrew)&quot;">​</a></h2><p>이미 <a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a>를 사용하고 있다면, 터미널에서 한 줄로 설치할 수 있다.</p><h3 id="c-1-homebrew로-설치" tabindex="-1">C-1. Homebrew로 설치 <a class="header-anchor" href="#c-1-homebrew로-설치" aria-label="Permalink to &quot;C-1. Homebrew로 설치&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span></span></code></pre></div><p><img src="'+A+`" alt="brew install node 실행 화면"></p><h3 id="c-2-설치-확인" tabindex="-1">C-2. 설치 확인 <a class="header-anchor" href="#c-2-설치-확인" aria-label="Permalink to &quot;C-2. 설치 확인&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p><img src="`+P+'" alt="Homebrew 설치 후 버전 확인"></p><p>버전 번호가 보이면 정상이다.</p><hr><blockquote><p>설치가 끝난 뒤에는 Antigravity IDE를 닫았다가 다시 여는 편이 안전하다. 새로 설치된 <code>node</code>/<code>npm</code> 명령을 IDE 터미널이 다시 읽어야 하기 때문이다.</p></blockquote><hr><p>← <a href="./git-bash-install.html">이전: Git Bash 설치 가이드</a> · <a href="./../user-guide.html">사용자 가이드 홈으로</a> · 다음: <a href="./claude-code-install.html">Claude Code 설치 가이드 →</a></p>',84)])])}const D=s(F,[["render",w]]);export{W as __pageData,D as default};
